-- State transitions declared for PosProfile (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION pos.pos_profiles_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'), ('inactive', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: pos_profiles.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS pos_profiles_status_transition_check ON pos.pos_profiles;
CREATE TRIGGER pos_profiles_status_transition_check
    BEFORE UPDATE OF "status" ON pos.pos_profiles
    FOR EACH ROW EXECUTE FUNCTION pos.pos_profiles_status_transition_check();
